import json
import os
from datetime import datetime

class Task:
    def __init__(self, title, description="", priority="medium", done=False):
        self.title = title
        self.description = description
        self.priority = priority
        self.done = done
        self.created = datetime.now().isoformat()

    def to_dict(self):
        return self.__dict__

    @classmethod
    def from_dict(cls, data):
        task = cls(data["title"], data["description"], data["priority"], data["done"])
        task.created = data.get("created", task.created)
        return task

    def __str__(self):
        status = "[X]" if self.done else "[ ]"
        return f"{status} {self.title} ({self.priority})"

class TaskManager:
    FILE = "tasks.json"

    def __init__(self):
        self.tasks = []
        self.load()

    def add(self, title, description="", priority="medium"):
        self.tasks.append(Task(title, description, priority))
        self.save()

    def list(self):
        if not self.tasks:
            print("No tasks yet.")
            return
        for i, task in enumerate(self.tasks, 1):
            print(f"{i}. {task}")

    def complete(self, index):
        try:
            self.tasks[index].done = True
            self.save()
            print("Task marked as done.")
        except IndexError:
            print("Invalid task number.")

    def delete(self, index):
        try:
            removed = self.tasks.pop(index)
            self.save()
            print(f"Deleted: {removed.title}")
        except IndexError:
            print("Invalid task number.")

    def save(self):
        with open(self.FILE, "w") as f:
            json.dump([t.to_dict() for t in self.tasks], f, indent=2)

    def load(self):
        if not os.path.exists(self.FILE):
            return
        try:
            with open(self.FILE, "r") as f:
                data = json.load(f)
                self.tasks = [Task.from_dict(item) for item in data]
        except (json.JSONDecodeError, IOError):
            print("Warning: Could not load tasks. Starting fresh.")
            self.tasks = []

def main():
    manager = TaskManager()

    while True:
        print("\n=== Task Manager ===")
        print("1. Add task")
        print("2. List tasks")
        print("3. Complete task")
        print("4. Delete task")
        print("5. Quit")

        choice = input("Choose: ").strip()

        if choice == "1":
            title = input("Title: ")
            desc = input("Description (optional): ")
            priority = input("Priority (low/medium/high): ") or "medium"
            manager.add(title, desc, priority)
        elif choice == "2":
            manager.list()
        elif choice == "3":
            manager.list()
            try:
                idx = int(input("Task number to complete: ")) - 1
                manager.complete(idx)
            except ValueError:
                print("Please enter a valid number.")
        elif choice == "4":
            manager.list()
            try:
                idx = int(input("Task number to delete: ")) - 1
                manager.delete(idx)
            except ValueError:
                print("Please enter a valid number.")
        elif choice == "5":
            print("Goodbye!")
            break
        else:
            print("Invalid choice.")

if __name__ == "__main__":
    main()
